export default [{"id":"2349","jozz":"16","page":"312","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"7","line_end":"7","aya_no":"1","aya_text":"طه","aya_text_emlaey":"طه","aya_tafseer":"[1] طه سبق الكلام على الحروف المقطَّعة في أول سورة البقرة."},{"id":"2350","jozz":"16","page":"312","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"7","line_end":"7","aya_no":"2","aya_text":"مَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ لِتَشۡقَىٰٓ","aya_text_emlaey":"ما أنـزلنا عليك القرآن لتشقى","aya_tafseer":"[2] ما أنزلنا عليك -أيها الرسول- القرآن؛ لتشقى بما لا طاقة لك به من العمل."},{"id":"2351","jozz":"16","page":"312","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"7","line_end":"8","aya_no":"3","aya_text":"إِلَّا تَذۡكِرَةٗ لِّمَن يَخۡشَىٰ","aya_text_emlaey":"إلا تذكرة لمن يخشى","aya_tafseer":"[3] لكن أنزلناه موعظة؛ ليتذكر به مَن يخاف عقاب الله، فيتقيه بأداء الفرائض واجتناب المحارم."},{"id":"2352","jozz":"16","page":"312","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"8","line_end":"8","aya_no":"4","aya_text":"تَنزِيلٗا مِّمَّنۡ خَلَقَ ٱلۡأَرۡضَ وَٱلسَّمَٰوَٰتِ ٱلۡعُلَى","aya_text_emlaey":"تنـزيلا ممن خلق الأرض والسموات العلا","aya_tafseer":"[4] هذا القرآن تنزيل من الله الذي خلق الأرض والسموات العلى."},{"id":"2353","jozz":"16","page":"312","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"9","line_end":"9","aya_no":"5","aya_text":"ٱلرَّحۡمَٰنُ عَلَى ٱلۡعَرۡشِ ٱسۡتَوَىٰ","aya_text_emlaey":"الرحمن على العرش استوى","aya_tafseer":"[5] الرحمن على العرش استوى، أي: علا وارتفع، استواء يليق بجلاله وعظمته."},{"id":"2354","jozz":"16","page":"312","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"9","line_end":"10","aya_no":"6","aya_text":"لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَمَا تَحۡتَ ٱلثَّرَىٰ","aya_text_emlaey":"له ما في السموات وما في الأرض وما بينهما وما تحت الثرى","aya_tafseer":"[6] له ما في السموات وما في الأرض وما بينهما وما تحت الأرض، خَلْقاً ومُلْكاً وتدبيراً."},{"id":"2355","jozz":"16","page":"312","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"10","line_end":"11","aya_no":"7","aya_text":"وَإِن تَجۡهَرۡ بِٱلۡقَوۡلِ فَإِنَّهُۥ يَعۡلَمُ ٱلسِّرَّ وَأَخۡفَى","aya_text_emlaey":"وإن تجهر بالقول فإنه يعلم السر وأخفى","aya_tafseer":"[7] وإن تجهر -أيها الرسول- بالقول، فتعلنه أو تخفه، فإن الله لا يخفى عليه شيء، يعلم السر وما هو أخفى من السر مما تحدِّث به نفسك."},{"id":"2356","jozz":"16","page":"312","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"11","line_end":"12","aya_no":"8","aya_text":"ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ لَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ","aya_text_emlaey":"الله لا إله إلا هو له الأسماء الحسنى","aya_tafseer":"[8] الله الذي لا معبود بحق إلا هو، له وحده الأسماء الكاملة في الحسن."},{"id":"2357","jozz":"16","page":"312","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"12","line_end":"12","aya_no":"9","aya_text":"وَهَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ","aya_text_emlaey":"وهل أتاك حديث موسى","aya_tafseer":"[9] وهل أتاك -أيها الرسول- خبر موسى بن عمران عليه السلام، وهو قادم من «مَدْيَن» إلى «مصر»؟"},{"id":"2358","jozz":"16","page":"312","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"12","line_end":"14","aya_no":"10","aya_text":"إِذۡ رَءَا نَارٗا فَقَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارٗا لَّعَلِّيٓ ءَاتِيكُم مِّنۡهَا بِقَبَسٍ أَوۡ أَجِدُ عَلَى ٱلنَّارِ هُدٗى","aya_text_emlaey":"إذ رأى نارا فقال لأهله امكثوا إني آنست نارا لعلي آتيكم منها بقبس أو أجد على النار هدى","aya_tafseer":"[10] حين رأى في الليل ناراً موقدة فقال لأهله: انتظروا لقد أبصرت ناراً، لعلي أجيئكم منها بشعلة تستدفئون بها، وتوقدون بها ناراً أخرى، أو أجد عندها هادياً يدلنا على الطريق."},{"id":"2359","jozz":"16","page":"312","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"14","line_end":"14","aya_no":"11","aya_text":"فَلَمَّآ أَتَىٰهَا نُودِيَ يَٰمُوسَىٰٓ","aya_text_emlaey":"فلما أتاها نودي ياموسى","aya_tafseer":"[11] فلما أتى موسى تلك النار ناداه الله: يا موسى،"},{"id":"2360","jozz":"16","page":"312","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"14","line_end":"15","aya_no":"12","aya_text":"إِنِّيٓ أَنَا۠ رَبُّكَ فَٱخۡلَعۡ نَعۡلَيۡكَ إِنَّكَ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوٗى","aya_text_emlaey":"إني أنا ربك فاخلع نعليك إنك بالواد المقدس طوى","aya_tafseer":"[12] ، إني أنا ربك فاخلع نعليك، إنك الآن بوادي «طوى» الذي باركته، وذلك استعداداً لمناجاة ربه."},{"id":"2361","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"1","line_end":"1","aya_no":"13","aya_text":"وَأَنَا ٱخۡتَرۡتُكَ فَٱسۡتَمِعۡ لِمَا يُوحَىٰٓ","aya_text_emlaey":"وأنا اخترتك فاستمع لما يوحى","aya_tafseer":"[13] وإني اخترتك يا موسى لرسالتي، فاستمع لما يوحى إليك مني."},{"id":"2362","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"1","line_end":"2","aya_no":"14","aya_text":"إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدۡنِي وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِيٓ","aya_text_emlaey":"إنني أنا الله لا إله إلا أنا فاعبدني وأقم الصلاة لذكري","aya_tafseer":"[14] إنني أنا الله لا معبود بحق إلا أنا، لا شريك لي، فاعبدني وحدي، وأقم الصلاة لتذكرني فيها."},{"id":"2363","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"2","line_end":"3","aya_no":"15","aya_text":"إِنَّ ٱلسَّاعَةَ ءَاتِيَةٌ أَكَادُ أُخۡفِيهَا لِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا تَسۡعَىٰ","aya_text_emlaey":"إن الساعة آتية أكاد أخفيها لتجزى كل نفس بما تسعى","aya_tafseer":"[15] إن الساعة التي يُبعث فيها الناس آتية لابد من وقوعها، أكاد أخفيها من نفسي، فكيف يعلمها أحد من المخلوقين؟ لكي تُجزى كل نفس بما عملت في الدنيا من خير أو شر."},{"id":"2364","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"3","line_end":"4","aya_no":"16","aya_text":"فَلَا يَصُدَّنَّكَ عَنۡهَا مَن لَّا يُؤۡمِنُ بِهَا وَٱتَّبَعَ هَوَىٰهُ فَتَرۡدَىٰ","aya_text_emlaey":"فلا يصدنك عنها من لا يؤمن بها واتبع هواه فتردى","aya_tafseer":"[16] فلا يصرفنَّك -يا موسى- عن الإيمان بها والاستعداد لها مَن لا يصدق بوقوعها ولا يعمل لها، واتبع هوى نفسه، فكذَّب بها، فتهلك."},{"id":"2365","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"4","line_end":"5","aya_no":"17","aya_text":"وَمَا تِلۡكَ بِيَمِينِكَ يَٰمُوسَىٰ","aya_text_emlaey":"وما تلك بيمينك ياموسى","aya_tafseer":"[17] وما هذه التي في يمينك يا موسى؟"},{"id":"2366","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"5","line_end":"6","aya_no":"18","aya_text":"قَالَ هِيَ عَصَايَ أَتَوَكَّؤُاْ عَلَيۡهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِي وَلِيَ فِيهَا مَـَٔارِبُ أُخۡرَىٰ","aya_text_emlaey":"قال هي عصاي أتوكأ عليها وأهش بها على غنمي ولي فيها مآرب أخرى","aya_tafseer":"[18] قال موسى: هي عصاي أعتمد عليها في المشي، وأهزُّ بها الشجر؛ لترعى غنمي ما يتساقط من ورقه، ولي فيها منافع أخرى."},{"id":"2367","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"6","line_end":"7","aya_no":"19","aya_text":"قَالَ أَلۡقِهَا يَٰمُوسَىٰ","aya_text_emlaey":"قال ألقها ياموسى","aya_tafseer":"[19] قال الله لموسى: ألق عصاك."},{"id":"2368","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"7","line_end":"7","aya_no":"20","aya_text":"فَأَلۡقَىٰهَا فَإِذَا هِيَ حَيَّةٞ تَسۡعَىٰ","aya_text_emlaey":"فألقاها فإذا هي حية تسعى","aya_tafseer":"[20] فألقاها موسى على الأرض، فانقلبت بإذن الله حية تسعى، فرأى موسى أمراً عظيماً وولى هارباً."},{"id":"2369","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"7","line_end":"8","aya_no":"21","aya_text":"قَالَ خُذۡهَا وَلَا تَخَفۡۖ سَنُعِيدُهَا سِيرَتَهَا ٱلۡأُولَىٰ","aya_text_emlaey":"قال خذها ولا تخف سنعيدها سيرتها الأولى","aya_tafseer":"[21] قال الله لموسى: خذ الحية، ولا تَخَفْ منها، سوف نعيدها عصاً كما كانت في حالتها الأولى."},{"id":"2370","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"8","line_end":"9","aya_no":"22","aya_text":"وَٱضۡمُمۡ يَدَكَ إِلَىٰ جَنَاحِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٍ ءَايَةً أُخۡرَىٰ","aya_text_emlaey":"واضمم يدك إلى جناحك تخرج بيضاء من غير سوء آية أخرى","aya_tafseer":"[22] . واضمم يدك إلى جنبك تحت العَضُد تخرج بيضاء كالثلج من غير برص؛ لتكون لك علامة أخرى."},{"id":"2371","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"9","line_end":"10","aya_no":"23","aya_text":"لِنُرِيَكَ مِنۡ ءَايَٰتِنَا ٱلۡكُبۡرَى","aya_text_emlaey":"لنريك من آياتنا الكبرى","aya_tafseer":"[23] فعلنا ذلك؛ لكي نريك -يا موسى- من أدلتنا الكبرى ما يدلُّ على قدرتنا، وعظيم سلطاننا، وصحة رسالتك."},{"id":"2372","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"10","line_end":"10","aya_no":"24","aya_text":"ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ","aya_text_emlaey":"اذهب إلى فرعون إنه طغى","aya_tafseer":"[24] اذهب -يا موسى- إلى فرعون؛ إنه قد تجاوز قدره وتمرَّد على ربه، فادعه إلى توحيد الله وعبادته."},{"id":"2373","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"10","line_end":"11","aya_no":"25","aya_text":"قَالَ رَبِّ ٱشۡرَحۡ لِي صَدۡرِي","aya_text_emlaey":"قال رب اشرح لي صدري","aya_tafseer":"[25] قال موسى: رب وسِّع لي صدري،"},{"id":"2374","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"11","line_end":"11","aya_no":"26","aya_text":"وَيَسِّرۡ لِيٓ أَمۡرِي","aya_text_emlaey":"ويسر لي أمري","aya_tafseer":"[26] وسَهِّل لي أمري،"},{"id":"2375","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"11","line_end":"12","aya_no":"27","aya_text":"وَٱحۡلُلۡ عُقۡدَةٗ مِّن لِّسَانِي","aya_text_emlaey":"واحلل عقدة من لساني","aya_tafseer":"[27] وأطلق لساني بفصيح المنطق؛"},{"id":"2376","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"12","line_end":"12","aya_no":"28","aya_text":"يَفۡقَهُواْ قَوۡلِي","aya_text_emlaey":"يفقهوا قولي","aya_tafseer":"[28] ليفهموا كلامي."},{"id":"2377","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"12","line_end":"12","aya_no":"29","aya_text":"وَٱجۡعَل لِّي وَزِيرٗا مِّنۡ أَهۡلِي","aya_text_emlaey":"واجعل لي وزيرا من أهلي","aya_tafseer":"[29] واجعل لي معيناً من أهلي،."},{"id":"2378","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"12","line_end":"13","aya_no":"30","aya_text":"هَٰرُونَ أَخِي","aya_text_emlaey":"هارون أخي","aya_tafseer":"[30] هارون أخي"},{"id":"2379","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"13","line_end":"13","aya_no":"31","aya_text":"ٱشۡدُدۡ بِهِۦٓ أَزۡرِي","aya_text_emlaey":"اشدد به أزري","aya_tafseer":"[31] قَوِّني به وشدَّ به ظهري،"},{"id":"2380","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"13","line_end":"13","aya_no":"32","aya_text":"وَأَشۡرِكۡهُ فِيٓ أَمۡرِي","aya_text_emlaey":"وأشركه في أمري","aya_tafseer":"[32] وأشركه معي في النبوة وتبليغ الرسالة؛"},{"id":"2381","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"13","line_end":"14","aya_no":"33","aya_text":"كَيۡ نُسَبِّحَكَ كَثِيرٗا","aya_text_emlaey":"كي نسبحك كثيرا","aya_tafseer":"[33] كي ننزهك بالتسبيح كثيراً."},{"id":"2382","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"14","line_end":"14","aya_no":"34","aya_text":"وَنَذۡكُرَكَ كَثِيرًا","aya_text_emlaey":"ونذكرك كثيرا","aya_tafseer":"[34] ونذكرك كثيراً فنحمدك."},{"id":"2383","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"14","line_end":"14","aya_no":"35","aya_text":"إِنَّكَ كُنتَ بِنَا بَصِيرٗا","aya_text_emlaey":"إنك كنت بنا بصيرا","aya_tafseer":"[35] إنك كنت بنا بصيراً، لا يخفى عليك شيء من أفعالنا."},{"id":"2384","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"14","line_end":"15","aya_no":"36","aya_text":"قَالَ قَدۡ أُوتِيتَ سُؤۡلَكَ يَٰمُوسَىٰ","aya_text_emlaey":"قال قد أوتيت سؤلك ياموسى","aya_tafseer":"[36] قال الله: قد أعطيتك كل ما سألت يا موسى."},{"id":"2385","jozz":"16","page":"313","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"15","line_end":"15","aya_no":"37","aya_text":"وَلَقَدۡ مَنَنَّا عَلَيۡكَ مَرَّةً أُخۡرَىٰٓ","aya_text_emlaey":"ولقد مننا عليك مرة أخرى","aya_tafseer":"[37] ولقد أنعمنا عليك -يا موسى- قبل هذه النعمة نعمة أخرى، حين كنت رضيعاً، فأنجيناك مِن بطش فرعون."},{"id":"2386","jozz":"16","page":"314","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"1","line_end":"1","aya_no":"38","aya_text":"إِذۡ أَوۡحَيۡنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ","aya_text_emlaey":"إذ أوحينا إلى أمك ما يوحى","aya_tafseer":"[38] وذلك حين ألهمْنا أمَّك:"},{"id":"2387","jozz":"16","page":"314","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"1","line_end":"3","aya_no":"39","aya_text":"أَنِ ٱقۡذِفِيهِ فِي ٱلتَّابُوتِ فَٱقۡذِفِيهِ فِي ٱلۡيَمِّ فَلۡيُلۡقِهِ ٱلۡيَمُّ بِٱلسَّاحِلِ يَأۡخُذۡهُ عَدُوّٞ لِّي وَعَدُوّٞ لَّهُۥۚ وَأَلۡقَيۡتُ عَلَيۡكَ مَحَبَّةٗ مِّنِّي وَلِتُصۡنَعَ عَلَىٰ عَيۡنِيٓ","aya_text_emlaey":"أن اقذفيه في التابوت فاقذفيه في اليم فليلقه اليم بالساحل يأخذه عدو لي وعدو له وألقيت عليك محبة مني ولتصنع على عيني","aya_tafseer":"[39] أن ضعي ابنك موسى بعد ولادته في التابوت ثم اطرحيه في النيل، فسوف يلقيه النيل على الساحل، فيأخذه فرعون عدوي وعدوه. وألقيت عليك محبة مني فصرت بذلك محبوباً بين العباد، ولِتَرْبَى على عيني وفي حفظي. وفي الآية إثبات صفة العين لله -سبحانه وتعالى- كما يليق بجلاله وكماله."},{"id":"2388","jozz":"16","page":"314","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"3","line_end":"6","aya_no":"40","aya_text":"إِذۡ تَمۡشِيٓ أُخۡتُكَ فَتَقُولُ هَلۡ أَدُلُّكُمۡ عَلَىٰ مَن يَكۡفُلُهُۥۖ فَرَجَعۡنَٰكَ إِلَىٰٓ أُمِّكَ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَۚ وَقَتَلۡتَ نَفۡسٗا فَنَجَّيۡنَٰكَ مِنَ ٱلۡغَمِّ وَفَتَنَّٰكَ فُتُونٗاۚ فَلَبِثۡتَ سِنِينَ فِيٓ أَهۡلِ مَدۡيَنَ ثُمَّ جِئۡتَ عَلَىٰ قَدَرٖ يَٰمُوسَىٰ","aya_text_emlaey":"إذ تمشي أختك فتقول هل أدلكم على من يكفله فرجعناك إلى أمك كي تقر عينها ولا تحزن وقتلت نفسا فنجيناك من الغم وفتناك فتونا فلبثت سنين في أهل مدين ثم جئت على قدر ياموسى","aya_tafseer":"[40] ومننَّا عليك حين تمشي أختك تتبعك ثم تقول لمن أخذوك: هل أدلكم على مَن يكفُله، ويرضعه لكم؟ فرددناك إلى أمِّك بعد ما صرتَ في أيدي فرعون؛ كي تطيب نفسها بسلامتك من الغرق والقتل، ولا تحزن على فَقْدك، وقتلت الرجل القبطي خطأ فنجيناك مِن غَمِّ فِعْلك وخوف القتل، وابتليناك ابتلاء، فخرجت خائفاً إلى أهل «مدين»، فمكثت سنين فيهم، ثم جئت من «مدين» في الموعد الذي قدَّرناه لإرسالك مجيئاً موافقاً لقدر الله وإرادته، والأمر كله لله تبارك وتعالى."},{"id":"2389","jozz":"16","page":"314","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"7","line_end":"7","aya_no":"41","aya_text":"وَٱصۡطَنَعۡتُكَ لِنَفۡسِي","aya_text_emlaey":"واصطنعتك لنفسي","aya_tafseer":"[41] وأنعمتُ عليك -يا موسى- هذه النعم اجتباء مني لك، واختياراً لرسالتي، والبلاغ عني، والقيام بأمري ونهيي."},{"id":"2390","jozz":"16","page":"314","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"7","line_end":"8","aya_no":"42","aya_text":"ٱذۡهَبۡ أَنتَ وَأَخُوكَ بِـَٔايَٰتِي وَلَا تَنِيَا فِي ذِكۡرِي","aya_text_emlaey":"اذهب أنت وأخوك بآياتي ولا تنيا في ذكري","aya_tafseer":"[42] اذهب -يا موسى- أنت وأخوك هارون بآياتي الدالة على ألوهيتي وكمال قدرتي وصدق رسالتك، ولا تَضْعُفا عن مداومة ذكري."},{"id":"2391","jozz":"16","page":"314","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"8","line_end":"8","aya_no":"43","aya_text":"ٱذۡهَبَآ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ","aya_text_emlaey":"اذهبا إلى فرعون إنه طغى","aya_tafseer":"[43] . اذهبا معاً إلى فرعون؛ إنه قد جاوز الحد في الكفر والظلم،"},{"id":"2392","jozz":"16","page":"314","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"8","line_end":"9","aya_no":"44","aya_text":"فَقُولَا لَهُۥ قَوۡلٗا لَّيِّنٗا لَّعَلَّهُۥ يَتَذَكَّرُ أَوۡ يَخۡشَىٰ","aya_text_emlaey":"فقولا له قولا لينا لعله يتذكر أو يخشى","aya_tafseer":"[44] فقولا له قولاً لطيفاً؛ لعله يتذكر أو يخاف ربه."},{"id":"2393","jozz":"16","page":"314","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"9","line_end":"10","aya_no":"45","aya_text":"قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفۡرُطَ عَلَيۡنَآ أَوۡ أَن يَطۡغَىٰ","aya_text_emlaey":"قالا ربنا إننا نخاف أن يفرط علينا أو أن يطغى","aya_tafseer":"[45] قال موسى وهارون: ربنا إننا نخاف أن يعاجلنا بالعقوبة، أو أن يتمرد على الحق فلا يقبله."},{"id":"2394","jozz":"16","page":"314","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"10","line_end":"10","aya_no":"46","aya_text":"قَالَ لَا تَخَافَآۖ إِنَّنِي مَعَكُمَآ أَسۡمَعُ وَأَرَىٰ","aya_text_emlaey":"قال لا تخافا إنني معكما أسمع وأرى","aya_tafseer":"[46] قال الله لموسى وهارون: لا تخافا من فرعون؛ فإنني معكما أسمع كلامكما وأرى أفعالكما،"},{"id":"2395","jozz":"16","page":"314","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"11","line_end":"13","aya_no":"47","aya_text":"فَأۡتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَٰٓءِيلَ وَلَا تُعَذِّبۡهُمۡۖ قَدۡ جِئۡنَٰكَ بِـَٔايَةٖ مِّن رَّبِّكَۖ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلۡهُدَىٰٓ","aya_text_emlaey":"فأتياه فقولا إنا رسولا ربك فأرسل معنا بني إسرائيل ولا تعذبهم قد جئناك بآية من ربك والسلام على من اتبع الهدى","aya_tafseer":"[47] فاذهبا إليه وقولا له: إننا رسولان إليك من ربك أن أطلق بني إسرائيل، ولا تكلِّفهم ما لا يطيقون من الأعمال، قد أتيناك بدلالة معجزة من ربك تدل على صدقنا في دعوتنا، والسلامة من عذاب الله تعالى لمن اتبع هداه. ."},{"id":"2396","jozz":"16","page":"314","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"13","line_end":"14","aya_no":"48","aya_text":"إِنَّا قَدۡ أُوحِيَ إِلَيۡنَآ أَنَّ ٱلۡعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ","aya_text_emlaey":"إنا قد أوحي إلينا أن العذاب على من كذب وتولى","aya_tafseer":"[48] إن ربك قد أوحى إلينا أن عذابه على مَن كذَّب وأعرض عن دعوته وشريعته."},{"id":"2397","jozz":"16","page":"314","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"14","line_end":"14","aya_no":"49","aya_text":"قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ","aya_text_emlaey":"قال فمن ربكما ياموسى","aya_tafseer":"[49] قال فرعون لهما -على وجه الإنكار-: فمَن ربكما يا موسى؟"},{"id":"2398","jozz":"16","page":"314","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"14","line_end":"15","aya_no":"50","aya_text":"قَالَ رَبُّنَا ٱلَّذِيٓ أَعۡطَىٰ كُلَّ شَيۡءٍ خَلۡقَهُۥ ثُمَّ هَدَىٰ","aya_text_emlaey":"قال ربنا الذي أعطى كل شيء خلقه ثم هدى","aya_tafseer":"[50] قال له موسى: ربُّنا الذي أعطى كلَّ شيء خَلْقَه اللائقَ به الدالَّ على حُسْن صُنْعه، ثم هدى كل مخلوق الهداية الكاملة إلى الانتفاع بما خلقه الله له."},{"id":"2399","jozz":"16","page":"314","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"15","line_end":"15","aya_no":"51","aya_text":"قَالَ فَمَا بَالُ ٱلۡقُرُونِ ٱلۡأُولَىٰ","aya_text_emlaey":"قال فما بال القرون الأولى","aya_tafseer":"[51] قال فرعون لموسى -على وجه المغالطة والمشاغبة-: فما شأن الأمم السابقة؟ وما خبر القرون الماضية، فقد سبقونا إلى الإنكار والكفر؟"},{"id":"2400","jozz":"16","page":"315","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"1","line_end":"1","aya_no":"52","aya_text":"قَالَ عِلۡمُهَا عِندَ رَبِّي فِي كِتَٰبٖۖ لَّا يَضِلُّ رَبِّي وَلَا يَنسَى","aya_text_emlaey":"قال علمها عند ربي في كتاب لا يضل ربي ولا ينسى","aya_tafseer":"[52] قال موسى لفرعون: ما سألتَ عنه ليس ممَّا نحن بصدده، بل عِلْمُ تلك القرون فيما فَعَلَت من ذلك عند ربي في اللوح المحفوظ، ولا عِلْمَ لي به، لا يضل ربي في أفعاله وأحكامه، ولا ينسى شيئاً ممَّا علمه منها."},{"id":"2401","jozz":"16","page":"315","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"1","line_end":"3","aya_no":"53","aya_text":"ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدٗا وَسَلَكَ لَكُمۡ فِيهَا سُبُلٗا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّن نَّبَاتٖ شَتَّىٰ","aya_text_emlaey":"الذي جعل لكم الأرض مهدا وسلك لكم فيها سبلا وأنـزل من السماء ماء فأخرجنا به أزواجا من نبات شتى","aya_tafseer":"[53] هو الذي جعل لكم الأرض ميسَّرة للانتفاع بها، وجعل لكم فيها طرقاً كثيرة، وأنزل من السماء مطراً، فأخرج به أنواعاً مختلفة من النبات."},{"id":"2402","jozz":"16","page":"315","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"3","line_end":"4","aya_no":"54","aya_text":"كُلُواْ وَٱرۡعَوۡاْ أَنۡعَٰمَكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ","aya_text_emlaey":"كلوا وارعوا أنعامكم إن في ذلك لآيات لأولي النهى","aya_tafseer":"[54] كلوا -أيها الناس- من طيبات ما أنبتنا لكم، وارعوا حيواناتكم وبهائمكم. إن في كل ما ذُكر لَعلامات على قدرة الله، ودعوة لوحدانيته وإفراده بالعبادة، لذوي العقول السليمة."},{"id":"2403","jozz":"16","page":"315","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"4","line_end":"5","aya_no":"55","aya_text":"۞ مِنۡهَا خَلَقۡنَٰكُمۡ وَفِيهَا نُعِيدُكُمۡ وَمِنۡهَا نُخۡرِجُكُمۡ تَارَةً أُخۡرَىٰ","aya_text_emlaey":"منها خلقناكم وفيها نعيدكم ومنها نخرجكم تارة أخرى","aya_tafseer":"[55] من الأرض خَلَقْناكم -أيها الناس-، وفيها نعيدكم بعد الموت، ومنها نخرجكم أحياء مرة أخرى للحساب والجزاء."},{"id":"2404","jozz":"16","page":"315","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"5","line_end":"6","aya_no":"56","aya_text":"وَلَقَدۡ أَرَيۡنَٰهُ ءَايَٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ","aya_text_emlaey":"ولقد أريناه آياتنا كلها فكذب وأبى","aya_tafseer":"[56] ولقد أرينا فرعون أدلتنا وحججنا جميعها، الدالةَ على ألوهيتنا وقدرتنا وصدْقِ رسالة موسى فكذَّب بها، وامتنع عن قَبول الحق."},{"id":"2405","jozz":"16","page":"315","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"6","line_end":"7","aya_no":"57","aya_text":"قَالَ أَجِئۡتَنَا لِتُخۡرِجَنَا مِنۡ أَرۡضِنَا بِسِحۡرِكَ يَٰمُوسَىٰ","aya_text_emlaey":"قال أجئتنا لتخرجنا من أرضنا بسحرك ياموسى","aya_tafseer":"[57] قال فرعون: هل جئتنا -يا موسى- لتخرجنا من ديارنا بسحرك هذا؟"},{"id":"2406","jozz":"16","page":"315","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"7","line_end":"9","aya_no":"58","aya_text":"فَلَنَأۡتِيَنَّكَ بِسِحۡرٖ مِّثۡلِهِۦ فَٱجۡعَلۡ بَيۡنَنَا وَبَيۡنَكَ مَوۡعِدٗا لَّا نُخۡلِفُهُۥ نَحۡنُ وَلَآ أَنتَ مَكَانٗا سُوٗى","aya_text_emlaey":"فلنأتينك بسحر مثله فاجعل بيننا وبينك موعدا لا نخلفه نحن ولا أنت مكانا سوى","aya_tafseer":"[58] فسوف نأتيك بسحر مثل سحرك، فاجعل بيننا وبينك موعداً محدداً، لا نخلفه نحن ولا تخلفه أنت، في مكان مستوٍ معتدل بيننا وبينك."},{"id":"2407","jozz":"16","page":"315","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"9","line_end":"9","aya_no":"59","aya_text":"قَالَ مَوۡعِدُكُمۡ يَوۡمُ ٱلزِّينَةِ وَأَن يُحۡشَرَ ٱلنَّاسُ ضُحٗى","aya_text_emlaey":"قال موعدكم يوم الزينة وأن يحشر الناس ضحى","aya_tafseer":"[59] قال موسى لفرعون: موعدكم للاجتماع يوم العيد ، حين يتزيَّن الناس، ويجتمعون من كل فج وناحية وقت الضحى."},{"id":"2408","jozz":"16","page":"315","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"10","line_end":"10","aya_no":"60","aya_text":"فَتَوَلَّىٰ فِرۡعَوۡنُ فَجَمَعَ كَيۡدَهُۥ ثُمَّ أَتَىٰ","aya_text_emlaey":"فتولى فرعون فجمع كيده ثم أتى","aya_tafseer":"[60] فأدبر فرعون معرضاً عما أتاه به موسى من الحق، فجمع سحرته، ثم جاء بعد ذلك لموعد الاجتماع."},{"id":"2409","jozz":"16","page":"315","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"10","line_end":"12","aya_no":"61","aya_text":"قَالَ لَهُم مُّوسَىٰ وَيۡلَكُمۡ لَا تَفۡتَرُواْ عَلَى ٱللَّهِ كَذِبٗا فَيُسۡحِتَكُم بِعَذَابٖۖ وَقَدۡ خَابَ مَنِ ٱفۡتَرَىٰ","aya_text_emlaey":"قال لهم موسى ويلكم لا تفتروا على الله كذبا فيسحتكم بعذاب وقد خاب من افترى","aya_tafseer":"[61] قال موسى لسحرة فرعون يعظهم: احذروا، لا تختلقوا على الله الكذب، فيستأصلكم بعذاب مِن عنده ويُبيدكم، وقد خسر من اختلق على الله كذباً."},{"id":"2410","jozz":"16","page":"315","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"12","line_end":"13","aya_no":"62","aya_text":"فَتَنَٰزَعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ وَأَسَرُّواْ ٱلنَّجۡوَىٰ","aya_text_emlaey":"فتنازعوا أمرهم بينهم وأسروا النجوى","aya_tafseer":"[62] فتجاذب السحرة أمرهم بينهم وتحادثوا سرّاً،"},{"id":"2411","jozz":"16","page":"315","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"13","line_end":"14","aya_no":"63","aya_text":"قَالُوٓاْ إِنۡ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخۡرِجَاكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِمَا وَيَذۡهَبَا بِطَرِيقَتِكُمُ ٱلۡمُثۡلَىٰ","aya_text_emlaey":"قالوا إن هذان لساحران يريدان أن يخرجاكم من أرضكم بسحرهما ويذهبا بطريقتكم المثلى","aya_tafseer":"[63] ، قالوا: إنْ موسى وهارون لساحران يريدان أن يخرجاكم من بلادكم بسحرهما، ويذهبا بطريقة السحر العظيمة التي أنتم عليها،"},{"id":"2412","jozz":"16","page":"315","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"15","line_end":"15","aya_no":"64","aya_text":"فَأَجۡمِعُواْ كَيۡدَكُمۡ ثُمَّ ٱئۡتُواْ صَفّٗاۚ وَقَدۡ أَفۡلَحَ ٱلۡيَوۡمَ مَنِ ٱسۡتَعۡلَىٰ","aya_text_emlaey":"فأجمعوا كيدكم ثم ائتوا صفا وقد أفلح اليوم من استعلى","aya_tafseer":"[64] فأحكموا كيدكم، واعزموا عليه من غير اختلاف بينكم، ثم ائتوا صفّاً واحداً، وألقوا ما في أيديكم مرة واحدة؛ لتَبْهَروا الأبصار، وتغلبوا سحر موسى وأخيه، وقد ظفر بحاجته اليوم مَن علا على صاحبه، فغلبه وقهره."},{"id":"2413","jozz":"16","page":"316","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"1","line_end":"1","aya_no":"65","aya_text":"قَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنۡ أَلۡقَىٰ","aya_text_emlaey":"قالوا ياموسى إما أن تلقي وإما أن نكون أول من ألقى","aya_tafseer":"[65] قال السحرة: يا موسى إما أن تلقي عصاك أولاً، وإما أن نبدأ نحن فنلقي ما معنا."},{"id":"2414","jozz":"16","page":"316","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"1","line_end":"3","aya_no":"66","aya_text":"قَالَ بَلۡ أَلۡقُواْۖ فَإِذَا حِبَالُهُمۡ وَعِصِيُّهُمۡ يُخَيَّلُ إِلَيۡهِ مِن سِحۡرِهِمۡ أَنَّهَا تَسۡعَىٰ","aya_text_emlaey":"قال بل ألقوا فإذا حبالهم وعصيهم يخيل إليه من سحرهم أنها تسعى","aya_tafseer":"[66] قال لهم موسى: بل ألقُوا أنتم ما معكم أولاً، فألقَوا حبالهم وعصيَّهم، فتخيل موسى مِن قوة سحرهم أنها حيات تسعى،"},{"id":"2415","jozz":"16","page":"316","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"3","line_end":"3","aya_no":"67","aya_text":"فَأَوۡجَسَ فِي نَفۡسِهِۦ خِيفَةٗ مُّوسَىٰ","aya_text_emlaey":"فأوجس في نفسه خيفة موسى","aya_tafseer":"[67] فشعر موسى في نفسه بالخوف."},{"id":"2416","jozz":"16","page":"316","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"3","line_end":"4","aya_no":"68","aya_text":"قُلۡنَا لَا تَخَفۡ إِنَّكَ أَنتَ ٱلۡأَعۡلَىٰ","aya_text_emlaey":"قلنا لا تخف إنك أنت الأعلى","aya_tafseer":"[68] قال الله لموسى حينئذ: لا تَخَفْ من شيء، فإنك أنت الأعلى على هؤلاء السحرة وعلى فرعون وجنوده، وستغلبهم."},{"id":"2417","jozz":"16","page":"316","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"4","line_end":"5","aya_no":"69","aya_text":"وَأَلۡقِ مَا فِي يَمِينِكَ تَلۡقَفۡ مَا صَنَعُوٓاْۖ إِنَّمَا صَنَعُواْ كَيۡدُ سَٰحِرٖۖ وَلَا يُفۡلِحُ ٱلسَّاحِرُ حَيۡثُ أَتَىٰ","aya_text_emlaey":"وألق ما في يمينك تلقف ما صنعوا إنما صنعوا كيد ساحر ولا يفلح الساحر حيث أتى","aya_tafseer":"[69] وألق عصاك التي في يمينك تبتلع حبالهم وعصيهم، فما عملوه أمامك ما هو إلا مكر ساحرٍ وتخييل سِحْرٍ، ولا يظفر الساحر بسحره أين كان."},{"id":"2418","jozz":"16","page":"316","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"5","line_end":"6","aya_no":"70","aya_text":"فَأُلۡقِيَ ٱلسَّحَرَةُ سُجَّدٗا قَالُوٓاْ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ","aya_text_emlaey":"فألقي السحرة سجدا قالوا آمنا برب هارون وموسى","aya_tafseer":"[70] فألقى موسى عصاه، فبلعت ما صنعوا، فظهر الحق وقامت الحجة عليهم. فألقى السحرة أنفسهم على الأرض ساجدين وقالوا: آمنا برب هارون وموسى، لو كان هذا سحراً ما غُلِبْنا."},{"id":"2419","jozz":"16","page":"316","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"6","line_end":"9","aya_no":"71","aya_text":"قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَۖ فَلَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ وَلَأُصَلِّبَنَّكُمۡ فِي جُذُوعِ ٱلنَّخۡلِ وَلَتَعۡلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابٗا وَأَبۡقَىٰ","aya_text_emlaey":"قال آمنتم له قبل أن آذن لكم إنه لكبيركم الذي علمكم السحر فلأقطعن أيديكم وأرجلكم من خلاف ولأصلبنكم في جذوع النخل ولتعلمن أينا أشد عذابا وأبقى","aya_tafseer":"[71] قال فرعون للسحرة: أصدَّقتم بموسى، واتبعتموه، وأقررتم له قبل أن آذن لكم بذلك؟ إن موسى لَعظيمكم الذي عَلَّمكم السحر؛ فلذلك تابعتموه، فلأقطعنَّ أيديكم وأرجلكم مخالفاً بينها، يداً من جهة ورِجْلاً من الجهة الأخرى، ولأصلبنَّكم -بربط أجسادكم- على جذوع النخل، ولتعلمنَّ أيها السحرة أينا: أنا أو رب موسى أشد عذاباً من الآخر، وأدوم له؟"},{"id":"2420","jozz":"16","page":"316","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"9","line_end":"11","aya_no":"72","aya_text":"قَالُواْ لَن نُّؤۡثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلَّذِي فَطَرَنَاۖ فَٱقۡضِ مَآ أَنتَ قَاضٍۖ إِنَّمَا تَقۡضِي هَٰذِهِ ٱلۡحَيَوٰةَ ٱلدُّنۡيَآ","aya_text_emlaey":"قالوا لن نؤثرك على ما جاءنا من البينات والذي فطرنا فاقض ما أنت قاض إنما تقضي هذه الحياة الدنيا","aya_tafseer":"[72] قال السحرة لفرعون: لن نفضلك، فنطيعك ونتبع دينك على ما جاءنا به موسى من البينات الدالة على صدقه، ووجوب متابعته وطاعة ربه، ولن نُفَضِّل ربوبيتك المزعومة على ربوبية الله الذي خلقنا، فافعل ما أنت فاعل بنا، إنما سلطانك في هذه الحياة الدنيا، وما تفعله بنا ما هو إلا عذاب منتهٍ بانتهائها."},{"id":"2421","jozz":"16","page":"316","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"11","line_end":"12","aya_no":"73","aya_text":"إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغۡفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكۡرَهۡتَنَا عَلَيۡهِ مِنَ ٱلسِّحۡرِۗ وَٱللَّهُ خَيۡرٞ وَأَبۡقَىٰٓ","aya_text_emlaey":"إنا آمنا بربنا ليغفر لنا خطايانا وما أكرهتنا عليه من السحر والله خير وأبقى","aya_tafseer":"[73] إنَّا آمنا بربنا وصدَّقْنا رسوله وعملنا بما جاء به؛ ليعفو ربُّنا عن ذنوبنا، وما أكرهتنا عليه مِن عمل السحر في معارضة موسى. والله خير لنا منك –يا فرعون- جزاء لمن أطاعه، وأبقى عذاباً لمن عصاه وخالف أمره."},{"id":"2422","jozz":"16","page":"316","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"12","line_end":"13","aya_no":"74","aya_text":"إِنَّهُۥ مَن يَأۡتِ رَبَّهُۥ مُجۡرِمٗا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ","aya_text_emlaey":"إنه من يأت ربه مجرما فإن له جهنم لا يموت فيها ولا يحيا","aya_tafseer":"[74] قال الله تعالى: إنَّ الأمرَ مَن يأت ربه كافراً به فإن له نار جهنم يُعَذَّب بها، لا يموت فيها فيستريح، ولا يحيا حياة يتلذذ بها."},{"id":"2423","jozz":"16","page":"316","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"13","line_end":"14","aya_no":"75","aya_text":"وَمَن يَأۡتِهِۦ مُؤۡمِنٗا قَدۡ عَمِلَ ٱلصَّٰلِحَٰتِ فَأُوْلَٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلۡعُلَىٰ","aya_text_emlaey":"ومن يأته مؤمنا قد عمل الصالحات فأولئك لهم الدرجات العلا","aya_tafseer":"[75] ومن يأت ربه مؤمناً به قد عمل الأعمال الصالحة فله المنازل العالية"},{"id":"2424","jozz":"16","page":"316","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"14","line_end":"15","aya_no":"76","aya_text":"جَنَّٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ","aya_text_emlaey":"جنات عدن تجري من تحتها الأنهار خالدين فيها وذلك جزاء من تزكى","aya_tafseer":"[76] في جنات الإقامة الدائمة، تجري من تحت قصورها وأشجارها الأنهار ماكثين فيها أبداً، وذلك النعيم المقيم ثواب من الله لمن طهَّر نفسه من الدنس والخبث والشرك، وعبد الله وحده فأطاعه واجتنب معاصيه، ولقي ربه لا يشرك بعبادته أحداً من خلقه."},{"id":"2425","jozz":"16","page":"317","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"1","line_end":"2","aya_no":"77","aya_text":"وَلَقَدۡ أَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِي فَٱضۡرِبۡ لَهُمۡ طَرِيقٗا فِي ٱلۡبَحۡرِ يَبَسٗا لَّا تَخَٰفُ دَرَكٗا وَلَا تَخۡشَىٰ","aya_text_emlaey":"ولقد أوحينا إلى موسى أن أسر بعبادي فاضرب لهم طريقا في البحر يبسا لا تخاف دركا ولا تخشى","aya_tafseer":"[77] ولقد أوحينا إلى موسى: أن اخرُج ليلاً بعبادي من بني إسرائيل من «مصر»، فاتَّخِذْ لهم في البحر طريقاً يابساً، لا تخاف من فرعون وجنوده أن يلحقوكم فيدركوكم، ولا تخشى في البحر غرقاً."},{"id":"2426","jozz":"16","page":"317","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"2","line_end":"3","aya_no":"78","aya_text":"فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلۡيَمِّ مَا غَشِيَهُمۡ","aya_text_emlaey":"فأتبعهم فرعون بجنوده فغشيهم من اليم ما غشيهم","aya_tafseer":"[78] فأسرى موسى ببني إسرائيل، وعبر بهم طريقاً في البحر، فأتبعهم فرعون بجنوده، فغمرهم من الماء ما لا يعلم كنهه إلا الله، فغرقوا جميعاً ونجا موسى وقومه."},{"id":"2427","jozz":"16","page":"317","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"3","line_end":"4","aya_no":"79","aya_text":"وَأَضَلَّ فِرۡعَوۡنُ قَوۡمَهُۥ وَمَا هَدَىٰ","aya_text_emlaey":"وأضل فرعون قومه وما هدى","aya_tafseer":"[79] وأضلَّ فرعون قومه بما زيَّنه لهم من الكفر والتكذيب، وما سلك بهم طريق الهداية."},{"id":"2428","jozz":"16","page":"317","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"4","line_end":"5","aya_no":"80","aya_text":"يَٰبَنِيٓ إِسۡرَٰٓءِيلَ قَدۡ أَنجَيۡنَٰكُم مِّنۡ عَدُوِّكُمۡ وَوَٰعَدۡنَٰكُمۡ جَانِبَ ٱلطُّورِ ٱلۡأَيۡمَنَ وَنَزَّلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰ","aya_text_emlaey":"يابني إسرائيل قد أنجيناكم من عدوكم وواعدناكم جانب الطور الأيمن ونـزلنا عليكم المن والسلوى","aya_tafseer":"[80] يا بني إسرائيل اذكروا حين أنجيناكم مِن عدوكم فرعون، وجَعَلْنا موعدكم الجانبَ الأيمنَ من جبل الطور لإنزال التوراة عليكم، ونزلنا عليكم في التيه ما تأكلونه، مما يشبه الصَّمْغ طعمه كالعسل والطير الذي يشبه السُّمَانَى."},{"id":"2429","jozz":"16","page":"317","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"5","line_end":"7","aya_no":"81","aya_text":"كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَلَا تَطۡغَوۡاْ فِيهِ فَيَحِلَّ عَلَيۡكُمۡ غَضَبِيۖ وَمَن يَحۡلِلۡ عَلَيۡهِ غَضَبِي فَقَدۡ هَوَىٰ","aya_text_emlaey":"كلوا من طيبات ما رزقناكم ولا تطغوا فيه فيحل عليكم غضبي ومن يحلل عليه غضبي فقد هوى","aya_tafseer":"[81] كلوا من رزقنا الطيب، ولا تعتدوا فيه بأن يظلم بعضكم بعضاً، فينزل بكم غضبي، ومَن ينزل به غضبي فقد هلك وخسر."},{"id":"2430","jozz":"16","page":"317","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"7","line_end":"8","aya_no":"82","aya_text":"وَإِنِّي لَغَفَّارٞ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا ثُمَّ ٱهۡتَدَىٰ","aya_text_emlaey":"وإني لغفار لمن تاب وآمن وعمل صالحا ثم اهتدى","aya_tafseer":"[82] وإني لَغفار لمن تاب من ذنبه وكفره، وآمن بي وعمل الأعمال الصالحة، ثم اهتدى إلى الحق واستقام عليه."},{"id":"2431","jozz":"16","page":"317","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"8","line_end":"9","aya_no":"83","aya_text":"۞ وَمَآ أَعۡجَلَكَ عَن قَوۡمِكَ يَٰمُوسَىٰ","aya_text_emlaey":"وما أعجلك عن قومك ياموسى","aya_tafseer":"[83] وأيُّ شيء أعجلك عن قومك -يا موسى- فسبقتَهم إلى جانب الطور الأيمن، وخلَّفتَهم وراءك؟"},{"id":"2432","jozz":"16","page":"317","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"9","line_end":"10","aya_no":"84","aya_text":"قَالَ هُمۡ أُوْلَآءِ عَلَىٰٓ أَثَرِي وَعَجِلۡتُ إِلَيۡكَ رَبِّ لِتَرۡضَىٰ","aya_text_emlaey":"قال هم أولاء على أثري وعجلت إليك رب لترضى","aya_tafseer":"[84] قال: إنهم خلفي سوف يلحقون بي، وسبقتُهم إليك -يا ربي- لتزداد عني رضا."},{"id":"2433","jozz":"16","page":"317","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"10","line_end":"11","aya_no":"85","aya_text":"قَالَ فَإِنَّا قَدۡ فَتَنَّا قَوۡمَكَ مِنۢ بَعۡدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِيُّ","aya_text_emlaey":"قال فإنا قد فتنا قومك من بعدك وأضلهم السامري","aya_tafseer":"[85] قال الله لموسى: فإنا قد ابتلينا قومك بعد فراقك إياهم بعبادة العجل، وإن السامري قد أضلهم."},{"id":"2434","jozz":"16","page":"317","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"11","line_end":"14","aya_no":"86","aya_text":"فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفٗاۚ قَالَ يَٰقَوۡمِ أَلَمۡ يَعِدۡكُمۡ رَبُّكُمۡ وَعۡدًا حَسَنًاۚ أَفَطَالَ عَلَيۡكُمُ ٱلۡعَهۡدُ أَمۡ أَرَدتُّمۡ أَن يَحِلَّ عَلَيۡكُمۡ غَضَبٞ مِّن رَّبِّكُمۡ فَأَخۡلَفۡتُم مَّوۡعِدِي","aya_text_emlaey":"فرجع موسى إلى قومه غضبان أسفا قال ياقوم ألم يعدكم ربكم وعدا حسنا أفطال عليكم العهد أم أردتم أن يحل عليكم غضب من ربكم فأخلفتم موعدي","aya_tafseer":"[86] فرجع موسى إلى قومه غضبان عليهم حزيناً، وقال لهم: يا قوم ألم يَعِدْكم ربكم وعداً حسناً بإنزال التوراة؟أفطال عليكم العهد واستبطأتم الوعد، أم أردتم أن تفعلوا فعلاً يحل عليكم بسببه غضب من ربكم، فأخلفتم موعدي وعبدتم العجل، وتركتم الالتزام بأوامري؟"},{"id":"2435","jozz":"16","page":"317","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"14","line_end":"15","aya_no":"87","aya_text":"قَالُواْ مَآ أَخۡلَفۡنَا مَوۡعِدَكَ بِمَلۡكِنَا وَلَٰكِنَّا حُمِّلۡنَآ أَوۡزَارٗا مِّن زِينَةِ ٱلۡقَوۡمِ فَقَذَفۡنَٰهَا فَكَذَٰلِكَ أَلۡقَى ٱلسَّامِرِيُّ","aya_text_emlaey":"قالوا ما أخلفنا موعدك بملكنا ولكنا حملنا أوزارا من زينة القوم فقذفناها فكذلك ألقى السامري","aya_tafseer":"[87] قالوا: يا موسى ما أخلفنا موعدك باختيارنا، ولكنَّا حُمِّلنا أثقالاً مِن حليِّ قوم فرعون، فألقيناها في حفرة فيها نار بأمر السامري، فكذلك ألقى السامري ما كان معه من تربة حافر فرس جبريل عليه السلام."},{"id":"2436","jozz":"16","page":"318","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"1","line_end":"2","aya_no":"88","aya_text":"فَأَخۡرَجَ لَهُمۡ عِجۡلٗا جَسَدٗا لَّهُۥ خُوَارٞ فَقَالُواْ هَٰذَآ إِلَٰهُكُمۡ وَإِلَٰهُ مُوسَىٰ فَنَسِيَ","aya_text_emlaey":"فأخرج لهم عجلا جسدا له خوار فقالوا هذا إلهكم وإله موسى فنسي","aya_tafseer":"[88] فصنع السامري لبني إسرائيل من الذهب عجلاً جسداً يخور خوار البقر، فقال المفتونون به منهم للآخرين: هذا هو إلهكم وإله موسى، نسيه وغَفَل عنه."},{"id":"2437","jozz":"16","page":"318","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"2","line_end":"3","aya_no":"89","aya_text":"أَفَلَا يَرَوۡنَ أَلَّا يَرۡجِعُ إِلَيۡهِمۡ قَوۡلٗا وَلَا يَمۡلِكُ لَهُمۡ ضَرّٗا وَلَا نَفۡعٗا","aya_text_emlaey":"أفلا يرون ألا يرجع إليهم قولا ولا يملك لهم ضرا ولا نفعا","aya_tafseer":"[89] أفلا يرى الذين عبدوا العجل أنه لا يكلمهم ابتداء، ولا يردُّ عليهم جواباً، ولا يقدر على دفع ضرٍّ عنهم، ولا جلب نفع لهم؟"},{"id":"2438","jozz":"16","page":"318","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"3","line_end":"5","aya_no":"90","aya_text":"وَلَقَدۡ قَالَ لَهُمۡ هَٰرُونُ مِن قَبۡلُ يَٰقَوۡمِ إِنَّمَا فُتِنتُم بِهِۦۖ وَإِنَّ رَبَّكُمُ ٱلرَّحۡمَٰنُ فَٱتَّبِعُونِي وَأَطِيعُوٓاْ أَمۡرِي","aya_text_emlaey":"ولقد قال لهم هارون من قبل ياقوم إنما فتنتم به وإن ربكم الرحمن فاتبعوني وأطيعوا أمري","aya_tafseer":"[90] ولقد قال هارون لبني إسرائيل من قبل رجوع موسى إليهم: يا قوم إنما اختُبرتم بهذا العجل؛ ليظهر المؤمن منكم من الكافر، وإن ربكم الرحمن لا غيره فاتبعوني فيما أدعوكم إليه من عبادة الله، وأطيعوا أمري في اتباع شرعه."},{"id":"2439","jozz":"16","page":"318","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"5","line_end":"6","aya_no":"91","aya_text":"قَالُواْ لَن نَّبۡرَحَ عَلَيۡهِ عَٰكِفِينَ حَتَّىٰ يَرۡجِعَ إِلَيۡنَا مُوسَىٰ","aya_text_emlaey":"قالوا لن نبرح عليه عاكفين حتى يرجع إلينا موسى","aya_tafseer":"[91] قال عُبَّاد العجل منهم: لن نزال مقيمين على عبادة العجل حتى يرجع إلينا موسى."},{"id":"2440","jozz":"16","page":"318","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"6","line_end":"6","aya_no":"92","aya_text":"قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذۡ رَأَيۡتَهُمۡ ضَلُّوٓاْ","aya_text_emlaey":"قال ياهارون ما منعك إذ رأيتهم ضلوا","aya_tafseer":"[92] قال موسى لأخيه هارون: أيُّ شيء منعك حين رأيتهم ضلُّوا عن دينهم"},{"id":"2441","jozz":"16","page":"318","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"7","line_end":"7","aya_no":"93","aya_text":"أَلَّا تَتَّبِعَنِۖ أَفَعَصَيۡتَ أَمۡرِي","aya_text_emlaey":"ألا تتبعن أفعصيت أمري","aya_tafseer":"[93] أن لا تتبعني، فتلحق بي وتتركهم؟ أفعصيت أمري فيما أمرتك به من خلافتي والإصلاح بعدي؟"},{"id":"2442","jozz":"16","page":"318","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"7","line_end":"9","aya_no":"94","aya_text":"قَالَ يَبۡنَؤُمَّ لَا تَأۡخُذۡ بِلِحۡيَتِي وَلَا بِرَأۡسِيٓۖ إِنِّي خَشِيتُ أَن تَقُولَ فَرَّقۡتَ بَيۡنَ بَنِيٓ إِسۡرَٰٓءِيلَ وَلَمۡ تَرۡقُبۡ قَوۡلِي","aya_text_emlaey":"قال يبنؤم لا تأخذ بلحيتي ولا برأسي إني خشيت أن تقول فرقت بين بني إسرائيل ولم ترقب قولي","aya_tafseer":"[94] ثم أخذ موسى بلحية هارون ورأسه يجرُّه إليه، فقال له هارون: يا بن أمي لا تمسك بلحيتي ولا بشعر رأسي، إني خفتُ -إن تركتهم ولحقت بك- أن تقول: فرَّقت بين بني إسرائيل، ولم تحفظ وصيتي بحسن رعايتهم."},{"id":"2443","jozz":"16","page":"318","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"9","line_end":"9","aya_no":"95","aya_text":"قَالَ فَمَا خَطۡبُكَ يَٰسَٰمِرِيُّ","aya_text_emlaey":"قال فما خطبك ياسامري","aya_tafseer":"[95] قال موسى للسامري: فما شأنك يا سامري؟ وما الذي دعاك إلى ما فعلته؟"},{"id":"2444","jozz":"16","page":"318","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"9","line_end":"11","aya_no":"96","aya_text":"قَالَ بَصُرۡتُ بِمَا لَمۡ يَبۡصُرُواْ بِهِۦ فَقَبَضۡتُ قَبۡضَةٗ مِّنۡ أَثَرِ ٱلرَّسُولِ فَنَبَذۡتُهَا وَكَذَٰلِكَ سَوَّلَتۡ لِي نَفۡسِي","aya_text_emlaey":"قال بصرت بما لم يبصروا به فقبضت قبضة من أثر الرسول فنبذتها وكذلك سولت لي نفسي","aya_tafseer":"[96] قال السامري: رأيت ما لم يروه -وهو جبريل عليه السلام- على فرس، وقت خروجهم من البحر وغرق فرعون وجنوده، فأخذتُ بكفي تراباً من أثر حافر فرس جبريل، فألقيته على الحليِّ الذي صَنعتُ منه العجل، فكان عجلاً جسداً له خوار؛ بلاء وفتنة، وكذلك زيَّنت لي نفسي الأمَّارة بالسوء هذا الصنيع."},{"id":"2445","jozz":"16","page":"318","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"11","line_end":"14","aya_no":"97","aya_text":"قَالَ فَٱذۡهَبۡ فَإِنَّ لَكَ فِي ٱلۡحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَۖ وَإِنَّ لَكَ مَوۡعِدٗا لَّن تُخۡلَفَهُۥۖ وَٱنظُرۡ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِي ظَلۡتَ عَلَيۡهِ عَاكِفٗاۖ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِي ٱلۡيَمِّ نَسۡفًا","aya_text_emlaey":"قال فاذهب فإن لك في الحياة أن تقول لا مساس وإن لك موعدا لن تخلفه وانظر إلى إلهك الذي ظلت عليه عاكفا لنحرقنه ثم لننسفنه في اليم نسفا","aya_tafseer":"[97] قال موسى للسامري: فاذهب فإن عقوبتك في الحياة الدنيا أن تعيش منبوذاً تقول لكل أحد: لا أَمَسُّ ولا أُمَسُّ، وإن لك موعداً في الآخرة لعذابك وعقابك، لن يُخْلفك الله إياه، وسوف تلقاه، وانظر إلى معبودك الذي أقمت على عبادته لنُحرقنَّه بالنار، ثم لنَذْرُونَّه في البحر ذَرْواً لتذهب به الريح؛ حتى لا يبقى منه أثر."},{"id":"2446","jozz":"16","page":"318","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"14","line_end":"15","aya_no":"98","aya_text":"إِنَّمَآ إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۚ وَسِعَ كُلَّ شَيۡءٍ عِلۡمٗا","aya_text_emlaey":"إنما إلهكم الله الذي لا إله إلا هو وسع كل شيء علما","aya_tafseer":"[98] إنما إلهكم -أيها الناس- هو الله الذي لا معبود بحق إلا هو، وسع علمه كل شيء."},{"id":"2447","jozz":"16","page":"319","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"1","line_end":"2","aya_no":"99","aya_text":"كَذَٰلِكَ نَقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآءِ مَا قَدۡ سَبَقَۚ وَقَدۡ ءَاتَيۡنَٰكَ مِن لَّدُنَّا ذِكۡرٗا","aya_text_emlaey":"كذلك نقص عليك من أنباء ما قد سبق وقد آتيناك من لدنا ذكرا","aya_tafseer":"[99] كما قصصنا عليك -أيها الرسول- أنباء موسى وفرعون وقومهما، نخبرك بأنباء السابقين لك. وقد آتيناك مِن عندنا هذا القرآن ذكرى لمن يتذكر."},{"id":"2448","jozz":"16","page":"319","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"2","line_end":"2","aya_no":"100","aya_text":"مَّنۡ أَعۡرَضَ عَنۡهُ فَإِنَّهُۥ يَحۡمِلُ يَوۡمَ ٱلۡقِيَٰمَةِ وِزۡرًا","aya_text_emlaey":"من أعرض عنه فإنه يحمل يوم القيامة وزرا","aya_tafseer":"[100] من أعرض عن هذا القرآن، ولم يصدق به، ولم يعمل بما فيه، فإنه يأتي ربه يوم القيامة يحمل إثماً عظيماً."},{"id":"2449","jozz":"16","page":"319","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"3","line_end":"3","aya_no":"101","aya_text":"خَٰلِدِينَ فِيهِۖ وَسَآءَ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ حِمۡلٗا","aya_text_emlaey":"خالدين فيه وساء لهم يوم القيامة حملا","aya_tafseer":"[101] خالدين في العذاب، وساءهم ذلك الحمل الثقيل من الآثام؛ حيث أوردهم النار."},{"id":"2450","jozz":"16","page":"319","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"3","line_end":"4","aya_no":"102","aya_text":"يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ وَنَحۡشُرُ ٱلۡمُجۡرِمِينَ يَوۡمَئِذٖ زُرۡقٗا","aya_text_emlaey":"يوم ينفخ في الصور ونحشر المجرمين يومئذ زرقا","aya_tafseer":"[102] يوم يَنفُخ الملَكُ في «القَرْن» لصيحة البعث، ونسوق الكافرين ذلكم اليوم وهم زرق، تغيَّرت ألوانهم وعيونهم؛ مِن شدة الأحداث والأهوال."},{"id":"2451","jozz":"16","page":"319","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"4","line_end":"5","aya_no":"103","aya_text":"يَتَخَٰفَتُونَ بَيۡنَهُمۡ إِن لَّبِثۡتُمۡ إِلَّا عَشۡرٗا","aya_text_emlaey":"يتخافتون بينهم إن لبثتم إلا عشرا","aya_tafseer":"[103] يتهامسون بينهم، يقول بعضهم لبعض: ما لبثتم في الحياة الدنيا إلا عشرة أيام."},{"id":"2452","jozz":"16","page":"319","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"5","line_end":"6","aya_no":"104","aya_text":"نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَ إِذۡ يَقُولُ أَمۡثَلُهُمۡ طَرِيقَةً إِن لَّبِثۡتُمۡ إِلَّا يَوۡمٗا","aya_text_emlaey":"نحن أعلم بما يقولون إذ يقول أمثلهم طريقة إن لبثتم إلا يوما","aya_tafseer":"[104] نحن أعلم بما يقولون ويُسِرُّون حين يقول أعلمهم وأوفاهم عقلاً: ما لبثتم إلا يوماً واحداً؛ لقِصَر مدة الدنيا في أنفسهم يوم القيامة."},{"id":"2453","jozz":"16","page":"319","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"6","line_end":"7","aya_no":"105","aya_text":"وَيَسۡـَٔلُونَكَ عَنِ ٱلۡجِبَالِ فَقُلۡ يَنسِفُهَا رَبِّي نَسۡفٗا","aya_text_emlaey":"ويسألونك عن الجبال فقل ينسفها ربي نسفا","aya_tafseer":"[105] ويسألك -أيها الرسول- قومك عن مصير الجبال يوم القيامة، فقل لهم: يزيلها ربِّي عن أماكنها فيجعلها هباء منبثّاً."},{"id":"2454","jozz":"16","page":"319","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"7","line_end":"7","aya_no":"106","aya_text":"فَيَذَرُهَا قَاعٗا صَفۡصَفٗا","aya_text_emlaey":"فيذرها قاعا صفصفا","aya_tafseer":"[106] فيترك الأرض حينئذ منبسطة مستوية ملساء لا نبات فيها،"},{"id":"2455","jozz":"16","page":"319","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"8","line_end":"8","aya_no":"107","aya_text":"لَّا تَرَىٰ فِيهَا عِوَجٗا وَلَآ أَمۡتٗا","aya_text_emlaey":"لا ترى فيها عوجا ولا أمتا","aya_tafseer":"[107] لا يرى الناظر إليها مِن استوائها مَيْلاً ولا ارتفاعاً ولا انخفاضاً."},{"id":"2456","jozz":"16","page":"319","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"8","line_end":"9","aya_no":"108","aya_text":"يَوۡمَئِذٖ يَتَّبِعُونَ ٱلدَّاعِيَ لَا عِوَجَ لَهُۥۖ وَخَشَعَتِ ٱلۡأَصۡوَاتُ لِلرَّحۡمَٰنِ فَلَا تَسۡمَعُ إِلَّا هَمۡسٗا","aya_text_emlaey":"يومئذ يتبعون الداعي لا عوج له وخشعت الأصوات للرحمن فلا تسمع إلا همسا","aya_tafseer":"[108] في ذلك اليوم يتبع الناس صوت الداعي إلى موقف القيامة، لا محيد عن دعوة الداعي؛ لأنها حق وصدق لجميع الخلق، وسكنت الأصوات خضوعاً للرحمن، فلا تسمع منها إلا صوتاً خفيّاً."},{"id":"2457","jozz":"16","page":"319","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"10","line_end":"11","aya_no":"109","aya_text":"يَوۡمَئِذٖ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَرَضِيَ لَهُۥ قَوۡلٗا","aya_text_emlaey":"يومئذ لا تنفع الشفاعة إلا من أذن له الرحمن ورضي له قولا","aya_tafseer":"[109] في ذلك اليوم لا تنفع الشفاعة أحداً من الخلق، إلا إذا أذن الرحمن للشافع، ورضي عن المشفوع له، ولا يكون ذلك إلا للمؤمن المخلص."},{"id":"2458","jozz":"16","page":"319","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"11","line_end":"12","aya_no":"110","aya_text":"يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يُحِيطُونَ بِهِۦ عِلۡمٗا","aya_text_emlaey":"يعلم ما بين أيديهم وما خلفهم ولا يحيطون به علما","aya_tafseer":"[110] يعلم الله ما بين أيدي الناس مِن أمر القيامة وما خلفهم من أمر الدنيا، ولا يحيط خلقه به علماً سبحانه وتعالى."},{"id":"2459","jozz":"16","page":"319","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"12","line_end":"13","aya_no":"111","aya_text":"۞ وَعَنَتِ ٱلۡوُجُوهُ لِلۡحَيِّ ٱلۡقَيُّومِۖ وَقَدۡ خَابَ مَنۡ حَمَلَ ظُلۡمٗا","aya_text_emlaey":"وعنت الوجوه للحي القيوم وقد خاب من حمل ظلما","aya_tafseer":"[111] وخضعت وجوه الخلائق وذلَّت لخالقها، الذي له جميع معاني الحياة الكاملة كما يليق بجلاله الذي لا يموت، القائم على تدبير كلِّ شيء، المستغني عمَّن سواه. وقد خسر يوم القيامة مَن أشرك مع الله أحداً من خلقه."},{"id":"2460","jozz":"16","page":"319","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"13","line_end":"14","aya_no":"112","aya_text":"وَمَن يَعۡمَلۡ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤۡمِنٞ فَلَا يَخَافُ ظُلۡمٗا وَلَا هَضۡمٗا","aya_text_emlaey":"ومن يعمل من الصالحات وهو مؤمن فلا يخاف ظلما ولا هضما","aya_tafseer":"[112] ومن يعمل صالحات الأعمال وهو مؤمن بربه، فلا يخاف ظلماً بزيادة سيئاته، ولا هضماً بنقص حسناته."},{"id":"2461","jozz":"16","page":"319","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"14","line_end":"15","aya_no":"113","aya_text":"وَكَذَٰلِكَ أَنزَلۡنَٰهُ قُرۡءَانًا عَرَبِيّٗا وَصَرَّفۡنَا فِيهِ مِنَ ٱلۡوَعِيدِ لَعَلَّهُمۡ يَتَّقُونَ أَوۡ يُحۡدِثُ لَهُمۡ ذِكۡرٗا","aya_text_emlaey":"وكذلك أنـزلناه قرآنا عربيا وصرفنا فيه من الوعيد لعلهم يتقون أو يحدث لهم ذكرا","aya_tafseer":"[113] وكما رغَّبنا أهل الإيمان في صالحات الأعمال، وحذَّرنا أهل الكفر من المقام على معاصيهم وكفرهم بآياتنا، أنزلنا هذا القرآن باللسان العربي؛ ليفهموه، وفصَّلنا فيه أنواعاً من الوعيد؛ رجاء أن يتقوا ربهم، أو يُحدِث لهم هذا القرآن تذكرة، فيتعظوا، ويعتبروا."},{"id":"2462","jozz":"16","page":"320","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"1","line_end":"2","aya_no":"114","aya_text":"فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۗ وَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن يُقۡضَىٰٓ إِلَيۡكَ وَحۡيُهُۥۖ وَقُل رَّبِّ زِدۡنِي عِلۡمٗا","aya_text_emlaey":"فتعالى الله الملك الحق ولا تعجل بالقرآن من قبل أن يقضى إليك وحيه وقل رب زدني علما","aya_tafseer":"[114] فتنزَّه الله -سبحانه- وارتفع، وتقدَّس عن كل نقص، الملِكُ الذي قهر سلطانُه كل ملك وجبار، المتصرف بكل شيء، الذي هو حق، ووعده حق، ووعيده حق، وكل شيء منه حق. ولا تعجل -أيها الرسول- بمسابقة جبريل في تَلَقِّي القرآن قبل أن يَفْرَغ منه، وقل: ربِّ زدني علماً إلى ما علمتني."},{"id":"2463","jozz":"16","page":"320","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"2","line_end":"3","aya_no":"115","aya_text":"وَلَقَدۡ عَهِدۡنَآ إِلَىٰٓ ءَادَمَ مِن قَبۡلُ فَنَسِيَ وَلَمۡ نَجِدۡ لَهُۥ عَزۡمٗا","aya_text_emlaey":"ولقد عهدنا إلى آدم من قبل فنسي ولم نجد له عزما","aya_tafseer":"[115] ولقد وصينا آدم مِن قَبلِ أن يأكل من الشجرة، ألَّا يأكل منها، وقلنا له: إن إبليس عدو لك ولزوجك، فلا يخرجنكما من الجنة، فتشقى أنت وزوجك في الدنيا، فوسوس إليه الشيطان، فأطاعه آدم ونسي الوصية، ولم نجد له قوة في العزم يحفظ بها ما أُمر به."},{"id":"2464","jozz":"16","page":"320","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"3","line_end":"4","aya_no":"116","aya_text":"وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ","aya_text_emlaey":"وإذ قلنا للملائكة اسجدوا لآدم فسجدوا إلا إبليس أبى","aya_tafseer":"[116] واذكر -أيها الرسول- إذ قلنا للملائكة: اسجدوا لآدم سجود تحية وإكرام، فأطاعوا وسجدوا، لكن إبليس امتنع من السجود."},{"id":"2465","jozz":"16","page":"320","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"5","line_end":"6","aya_no":"117","aya_text":"فَقُلۡنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوّٞ لَّكَ وَلِزَوۡجِكَ فَلَا يُخۡرِجَنَّكُمَا مِنَ ٱلۡجَنَّةِ فَتَشۡقَىٰٓ","aya_text_emlaey":"فقلنا ياآدم إن هذا عدو لك ولزوجك فلا يخرجنكما من الجنة فتشقى","aya_tafseer":"[117] فقلنا: يا آدم إن إبليس هذا عدو لك ولزوجتك، فاحذرا منه ولا تطيعاه بمعصيتي، فيخرجكما من الجنة، فتشقى إذا أُخرجت منها."},{"id":"2466","jozz":"16","page":"320","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"6","line_end":"6","aya_no":"118","aya_text":"إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعۡرَىٰ","aya_text_emlaey":"إن لك ألا تجوع فيها ولا تعرى","aya_tafseer":"[118] إن لك -يا آدم- نِعْمةً تامَّةً وعطيَّةً مستمرَّةً في هذه الجنة أن تأكل فلا تجوع، وأن تَلْبَس فلا تَعْرى."},{"id":"2467","jozz":"16","page":"320","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"7","line_end":"7","aya_no":"119","aya_text":"وَأَنَّكَ لَا تَظۡمَؤُاْ فِيهَا وَلَا تَضۡحَىٰ","aya_text_emlaey":"وأنك لا تظمأ فيها ولا تضحى","aya_tafseer":"[119] وأن لك ألا تعطش في هذه الجنة ولا يصيبك حر الشمس."},{"id":"2468","jozz":"16","page":"320","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"7","line_end":"9","aya_no":"120","aya_text":"فَوَسۡوَسَ إِلَيۡهِ ٱلشَّيۡطَٰنُ قَالَ يَٰٓـَٔادَمُ هَلۡ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلۡخُلۡدِ وَمُلۡكٖ لَّا يَبۡلَىٰ","aya_text_emlaey":"فوسوس إليه الشيطان قال ياآدم هل أدلك على شجرة الخلد وملك لا يبلى","aya_tafseer":"[120] فوسوس الشيطان لآدم وقال له: هل أدلك على شجرة، إن أكلت منها خُلِّدتَ فلم تمت، وملكت مُلْكاً لا ينقضي ولا ينقطع؟"},{"id":"2469","jozz":"16","page":"320","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"9","line_end":"10","aya_no":"121","aya_text":"فَأَكَلَا مِنۡهَا فَبَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ","aya_text_emlaey":"فأكلا منها فبدت لهما سوآتهما وطفقا يخصفان عليهما من ورق الجنة وعصى آدم ربه فغوى","aya_tafseer":"[121] فأكل آدم وحواء من الشجرة التي نهاهما الله عنها، فانكشفت لهما عوراتهما، وكانت مستورةً عن أعينهما، فأخذا ينزعان من ورق أشجار الجنة ويلصقانه عليهما؛ ليسترا ما انكشف من عوراتهما، وخالف آدم أمر ربه، فغوى بالأكل من الشجرة التي نهاه الله عن الاقتراب منها."},{"id":"2470","jozz":"16","page":"320","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"11","line_end":"11","aya_no":"122","aya_text":"ثُمَّ ٱجۡتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيۡهِ وَهَدَىٰ","aya_text_emlaey":"ثم اجتباه ربه فتاب عليه وهدى","aya_tafseer":"[122] ثم اصطفى الله آدم وقرَّبه، وقَبِل توبته، وهداه رشده."},{"id":"2471","jozz":"16","page":"320","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"11","line_end":"13","aya_no":"123","aya_text":"قَالَ ٱهۡبِطَا مِنۡهَا جَمِيعَۢاۖ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدٗى فَمَنِ ٱتَّبَعَ هُدَايَ فَلَا يَضِلُّ وَلَا يَشۡقَىٰ","aya_text_emlaey":"قال اهبطا منها جميعا بعضكم لبعض عدو فإما يأتينكم مني هدى فمن اتبع هداي فلا يضل ولا يشقى","aya_tafseer":"[123] قال الله تعالى لآدم وحواء: اهبطا من الجنة إلى الأرض جميعاً مع إبليس، فأنتما وهو أعداء، فإن يأتكم مني هدى وبيان فمن اتبع هداي وبياني وعمل بهما فإنه يرشد في الدنيا، ويهتدي، ولا يشقى في الآخرة بعقاب الله."},{"id":"2472","jozz":"16","page":"320","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"13","line_end":"15","aya_no":"124","aya_text":"وَمَنۡ أَعۡرَضَ عَن ذِكۡرِي فَإِنَّ لَهُۥ مَعِيشَةٗ ضَنكٗا وَنَحۡشُرُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ أَعۡمَىٰ","aya_text_emlaey":"ومن أعرض عن ذكري فإن له معيشة ضنكا ونحشره يوم القيامة أعمى","aya_tafseer":"[124] ومن تولَّى عن ذكري الذي أذكِّره به فإن له في الحياة الأولى معيشة ضيِّقة شاقة -وإن ظهر أنه من أهل الفضل واليسار-، ويُضيَّق قبره عليه ويعذَّب فيه، ونحشره يوم القيامة أعمى عن الرؤية وعن الحجة."},{"id":"2473","jozz":"16","page":"320","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"15","line_end":"15","aya_no":"125","aya_text":"قَالَ رَبِّ لِمَ حَشَرۡتَنِيٓ أَعۡمَىٰ وَقَدۡ كُنتُ بَصِيرٗا","aya_text_emlaey":"قال رب لم حشرتني أعمى وقد كنت بصيرا","aya_tafseer":"[125] قال المعرِض عن ذكر الله: ربِّ لِمَ حَشَرْتني أعمى، وقد كنت بصيراً في الدنيا؟"},{"id":"2474","jozz":"16","page":"321","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"1","line_end":"1","aya_no":"126","aya_text":"قَالَ كَذَٰلِكَ أَتَتۡكَ ءَايَٰتُنَا فَنَسِيتَهَاۖ وَكَذَٰلِكَ ٱلۡيَوۡمَ تُنسَىٰ","aya_text_emlaey":"قال كذلك أتتك آياتنا فنسيتها وكذلك اليوم تنسى","aya_tafseer":"[126] قال الله تعالى له: حشرتك أعمى؛ لأنك أتتك آياتي البيناتُ، فأعرضتَ عنها، ولم تؤمن بها، وكما تركتَها في الدنيا فكذلك اليوم تُترك في النار."},{"id":"2475","jozz":"16","page":"321","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"2","line_end":"3","aya_no":"127","aya_text":"وَكَذَٰلِكَ نَجۡزِي مَنۡ أَسۡرَفَ وَلَمۡ يُؤۡمِنۢ بِـَٔايَٰتِ رَبِّهِۦۚ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَشَدُّ وَأَبۡقَىٰٓ","aya_text_emlaey":"وكذلك نجزي من أسرف ولم يؤمن بآيات ربه ولعذاب الآخرة أشد وأبقى","aya_tafseer":"[127] وهكذا نعاقب مَن أسرف على نفسه فعصى ربه، ولم يؤمن بآياته بعقوبات في الدنيا، ولَعذاب الآخرة المعدُّ لهم أشد ألماً وأدوم وأثبت؛ لأنه لا ينقطع ولا ينقضي."},{"id":"2476","jozz":"16","page":"321","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"3","line_end":"4","aya_no":"128","aya_text":"أَفَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ","aya_text_emlaey":"أفلم يهد لهم كم أهلكنا قبلهم من القرون يمشون في مساكنهم إن في ذلك لآيات لأولي النهى","aya_tafseer":"[128] أفلم يدلَّ قومَك -أيها الرسول- على طريق الرشاد كثرةُ مَن أهلكنا من الأمم المكذبة قبلَهم، وهم يمشون في ديارهم، ويرون آثار هلاكهم؟ إن في كثرة تلك الأمم وآثار عذابهم لَعبراً وعظاتٍ لأهل العقول الواعية."},{"id":"2477","jozz":"16","page":"321","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"5","line_end":"5","aya_no":"129","aya_text":"وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَكَانَ لِزَامٗا وَأَجَلٞ مُّسَمّٗى","aya_text_emlaey":"ولولا كلمة سبقت من ربك لكان لزاما وأجل مسمى","aya_tafseer":"[129] ولولا كلمةٌ سبقت من ربك بتأخير العذاب عنهم، وأجلٌ مسمَّى يَقَعُ عنده الهلاك للازمهم في الدنيا عاجلاً؛ لأنهم يستحقونه؛ بسبب كفرهم."},{"id":"2478","jozz":"16","page":"321","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"6","line_end":"8","aya_no":"130","aya_text":"فَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ غُرُوبِهَاۖ وَمِنۡ ءَانَآيِٕ ٱلَّيۡلِ فَسَبِّحۡ وَأَطۡرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرۡضَىٰ","aya_text_emlaey":"فاصبر على ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل غروبها ومن آناء الليل فسبح وأطراف النهار لعلك ترضى","aya_tafseer":"[130] فاصبر -أيها الرسول- على ما يقوله المكذبون بك من أوصاف وأباطيل، وسبِّح بحمد ربك في صلاة الفجر قبل طلوع الشمس، وفي صلاة العصر قبل غروبها، وفي صلاة العشاء في ساعات الليل، وسبِّح بحمد ربك أطرافَ النهار في صلاة الظهر -إذ وقتها طرف النصف الأول والنصف الثاني من النهار- وفي صلاة المغرب؛ كي تثاب على هذه الأعمال بما تَرْضى به."},{"id":"2479","jozz":"16","page":"321","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"8","line_end":"9","aya_no":"131","aya_text":"وَلَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ زَهۡرَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا لِنَفۡتِنَهُمۡ فِيهِۚ وَرِزۡقُ رَبِّكَ خَيۡرٞ وَأَبۡقَىٰ","aya_text_emlaey":"ولا تمدن عينيك إلى ما متعنا به أزواجا منهم زهرة الحياة الدنيا لنفتنهم فيه ورزق ربك خير وأبقى","aya_tafseer":"[131] ولا تنظر إلى ما مَتَّعْنا به هؤلاء المشركين وأمثالَهم من أنواع المتع، فإنها زينة زائلة في هذه الحياة الدنيا، متعناهم بها؛ لنبتليهم بها، ورزق ربك وثوابه خير لك مما متعناهم به وأدوم؛ حيث لا انقطاع له ولا نفاد."},{"id":"2480","jozz":"16","page":"321","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"9","line_end":"11","aya_no":"132","aya_text":"وَأۡمُرۡ أَهۡلَكَ بِٱلصَّلَوٰةِ وَٱصۡطَبِرۡ عَلَيۡهَاۖ لَا نَسۡـَٔلُكَ رِزۡقٗاۖ نَّحۡنُ نَرۡزُقُكَۗ وَٱلۡعَٰقِبَةُ لِلتَّقۡوَىٰ","aya_text_emlaey":"وأمر أهلك بالصلاة واصطبر عليها لا نسألك رزقا نحن نرزقك والعاقبة للتقوى","aya_tafseer":"[132] وَأْمُرْ -أيها النبي- أهلك بالصلاة، واصطبر على أدائها، لا نسألك مالاً، نحن نرزقك ونعطيك. والعاقبة الصالحة في الدنيا والآخرة لأهل التقوى."},{"id":"2481","jozz":"16","page":"321","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"11","line_end":"12","aya_no":"133","aya_text":"وَقَالُواْ لَوۡلَا يَأۡتِينَا بِـَٔايَةٖ مِّن رَّبِّهِۦٓۚ أَوَلَمۡ تَأۡتِهِم بَيِّنَةُ مَا فِي ٱلصُّحُفِ ٱلۡأُولَىٰ","aya_text_emlaey":"وقالوا لولا يأتينا بآية من ربه أو لم تأتهم بينة ما في الصحف الأولى","aya_tafseer":"[133] وقال مكذبوك -أيها الرسول-: هلَّا تأتينا بعلامة من ربك تدلُّ على صدقك، أو لم يأتهم هذا القرآن المصدق لما في الكتب السابقة من الحق؟"},{"id":"2482","jozz":"16","page":"321","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"12","line_end":"14","aya_no":"134","aya_text":"وَلَوۡ أَنَّآ أَهۡلَكۡنَٰهُم بِعَذَابٖ مِّن قَبۡلِهِۦ لَقَالُواْ رَبَّنَا لَوۡلَآ أَرۡسَلۡتَ إِلَيۡنَا رَسُولٗا فَنَتَّبِعَ ءَايَٰتِكَ مِن قَبۡلِ أَن نَّذِلَّ وَنَخۡزَىٰ","aya_text_emlaey":"ولو أنا أهلكناهم بعذاب من قبله لقالوا ربنا لولا أرسلت إلينا رسولا فنتبع آياتك من قبل أن نذل ونخزى","aya_tafseer":"[134] ولو أنَّا أهلكنا هؤلاء المكذبين بعذاب مِن قبل أن نرسل إليهم رسولاً وننزل عليهم كتاباً لقالوا: ربنا هلَّا أرسلت إلينا رسولاً مِن عندك، فنصدقَه، ونتبع آياتك وشرعَك، مِن قبل أن نَذلَّ ونَخزى بعذابك."},{"id":"2483","jozz":"16","page":"321","sura_no":"20","sura_name_en":"Ṭā-Hā","sura_name_ar":"طه ","line_start":"14","line_end":"15","aya_no":"135","aya_text":"قُلۡ كُلّٞ مُّتَرَبِّصٞ فَتَرَبَّصُواْۖ فَسَتَعۡلَمُونَ مَنۡ أَصۡحَٰبُ ٱلصِّرَٰطِ ٱلسَّوِيِّ وَمَنِ ٱهۡتَدَىٰ","aya_text_emlaey":"قل كل متربص فتربصوا فستعلمون من أصحاب الصراط السوي ومن اهتدى","aya_tafseer":"[135] قل -أيها الرسول- لهؤلاء المشركين بالله: كل منا ومنكم منتظر دوائر الزمان، ولمن يكون النصر والفلاح، فانتظروا، فستعلمون: مَن أهل الطريق المستقيم، ومَن المهتدي للحق منا ومنكم؟"}]
